Equiv.piEquivPiSubtypeProd:
def VTask.piEquivPiSubtypeProd {α : Type u_9} (p : α → Prop) (β : α → Type u_10) [DecidablePred p] :
    ((i : α) → β i) ≃ ((i : { x // p x }) → β ↑i) × ((i : { x // ¬p x }) → β ↑i) :=
  {
    toFun := fun f => (fun ⟨x, hx⟩ => f x, fun ⟨x, hx⟩ => f x)
    invFun := fun ⟨f₁, f₂⟩ => fun x => if hx : p x then f₁ ⟨x, hx⟩ else f₂ ⟨x, hx⟩
    left_inv := by
      intro f
      funext x
      by_cases hx : p x <;> simp [hx]
      <;> aesop
    right_inv := by
      intro ⟨f₁, f₂⟩
      ext <;> simp_all [Subtype.ext_iff]
      <;>
      (try
        {
          aesop
        })
      <;>
      (try
        {
          by_cases hx : p x <;> simp_all [hx]
          <;> aesop
        })
      <;>
      (try
        {
          aesop
        })
  }

Filter.Germ.IsConstant:
def VTask.IsConstant : {α : Type u_1} -> {β : Type u_2} -> {l : Filter α} -> (P : l.Germ β) -> Prop :=
  fun {α} {β} {l} P =>
    ∃ (b : β) (f : α → β) (s : Set α), P = f ∧ s ∈ l ∧ ∀ x ∈ s, f x = b

Function.Embedding.setValue:
def VTask.setValue {α : Sort u_1} {β : Sort u_2} (f : α ↪ β) (a : α) (b : β) 
    [∀ (a' : α), Decidable (a' = a)] [∀ (a' : α), Decidable (f a' = b)] : α ↪ β :=
  let g : α → β :=
    fun x => if h : x = a then b else
      if h' : f x = b then f a else f x
  ⟨g, fun x y h => by
    simp only [g] at h ⊢
    split_ifs at h ⊢ <;>
    (try { contradiction }) <;>
    (try {
      simp_all [Function.Embedding.injective]
      <;>
      (try { aesop }) <;>
      (try {
        have h₁ := f.injective
        specialize h₁ h
        simp_all
      })
    }) <;>
    (try {
      have h₁ := f.injective
      specialize h₁ h
      simp_all
      <;>
      (try { aesop })
    }) <;>
    (try {
      simp_all [Function.Embedding.injective]
      <;>
      (try { aesop })
    }) <;>
    (try {
      aesop
    })
  ⟩

Nat.divisors:
def VTask.divisors (n : ℕ) : Finset ℕ :=
  if n = 0 then ∅ else
  Finset.filter (fun x => x ∣ n) (Finset.Icc 1 n)

