Nat.nthRoot:
def VTask.nthRoot (n a : ℕ) : ℕ :=
  if n = 0 then 1 else
    Nat.findGreatest (fun r => r ^ n ≤ a) a

Relation.Fibration:
def VTask.Fibration : {α : Type u_1} -> {β : Type u_2} -> (rα : α → α → Prop) -> (rβ : β → β → Prop) -> (f : α → β) -> Prop :=
  fun {α} {β} rα rβ f =>
    ∀ (a : α) (b : β), rβ b (f a) → ∃ (a' : α), rα a' a ∧ f a' = b

Relation.Map:
def VTask.Map : {α : Type u_1} -> {β : Type u_2} -> {γ : Type u_3} -> {δ : Type u_4} -> (r : α → β → Prop) -> (f : α → γ) -> (g : β → δ) -> γ → δ → Prop :=
  fun {α} {β} {γ} {δ} r f g c d =>
    ∃ (a : α) (b : β), r a b ∧ f a = c ∧ g b = d

memPartition:
def VTask.memPartition {α : Type u} (f : ℕ → Set α) : ℕ → Set (Set α)
  | 0 => {Set.univ}
  | n + 1 =>
    let s := VTask.memPartition f n
    s.image (fun t => t ∩ f n) ∪ s.image (fun t => t \ f n)
